#include <stdio.h>
#include <string.h>

#define V 6
#define INF 0x3f3f3f3f

int g[V][V];
int dist[V];
int q[V * V];

int main(void) {
    int edges[][2] = {{0,1},{0,2},{1,3},{1,4},{2,4},{3,5},{4,5}};
    int m = (int)(sizeof(edges) / sizeof(edges[0]));
    for (int i = 0; i < m; i++) {
        int u = edges[i][0], v = edges[i][1];
        g[u][v] = g[v][u] = 1;
    }

    for (int i = 0; i < V; i++) dist[i] = INF;

    int front = 0, rear = 0;
    int s = 0;
    dist[s] = 0;
    q[rear++] = s;
    int level = -1;

    printf("BFS 从 %d 出发：\n", s);
    while (front < rear) {
        int sz = rear - front;
        level++;
        printf("  第 %d 层：", level);
        for (int i = 0; i < sz; i++) {
            int u = q[front++];
            printf("%d(dist=%d) ", u, dist[u]);
            for (int v = 0; v < V; v++) {
                if (!g[u][v]) continue;
                if (dist[v] == INF) {
                    dist[v] = dist[u] + 1;   /* 关键：入队时确定，不是出队时 */
                    q[rear++] = v;
                }
            }
        }
        printf("\n");
    }

    printf("\n各点最短距离：");
    for (int i = 0; i < V; i++)
        printf("%d:%d ", i, dist[i] == INF ? -1 : dist[i]);
    printf("\n");

    printf("\n要点：BFS 队列中的距离序列非降，故每点首次入队时 dist 即为最短。\n");
    printf("      这就是它能求「无权最短路 / 最少步数 / 几度好友」的原因。\n");
    return 0;
}
